const rows = [];
const seen = new Set();

for (let run = 0; run < 1000; run++) {
  let items;

  try {
    items = $('Score Test Case').all(0, run);
  } catch (e) {
    break;
  }

  if (!items || items.length === 0) break;

  let newRecords = 0;

  for (const item of items) {
    const row = item.json;

    if (!row || !row.test_id) continue;

    const key = `${row.eval_run_id ?? ''}:${row.test_id}`;

    if (seen.has(key)) continue;

    seen.add(key);
    rows.push(row);
    newRecords++;
  }

  if (newRecords === 0) break;
}

const n = rows.length;

const finalPass = row => {
  if (row.overall_eval_pass === true ||
      row.overall_eval_pass === false) {
    return row.overall_eval_pass;
  }

  return row.passed === true;
};

const passed = rows.filter(finalPass).length;

function avg(key) {
  const values = rows
    .map(r => r[key])
    .filter(v =>
      v !== null &&
      v !== undefined &&
      v !== '' &&
      Number.isFinite(Number(v))
    )
    .map(Number);

  if (!values.length) return null;

  return Math.round(
    values.reduce((sum, v) => sum + v, 0) /
    values.length * 10
  ) / 10;
}

return [{
  json: {
    test_cases: n,
    passed,
    failed: n - passed,

    pass_rate_pct: n
      ? Math.round(passed / n * 1000) / 10
      : null,

    avg_grounding_coverage_pct:
      avg('grounding_coverage'),

    avg_latency_ms:
      avg('latency_ms'),

    failures: rows
      .filter(r => !finalPass(r))
      .map(r => ({
        test_id: r.test_id,
        capability: r.capability,
        issues: r.evaluation_issues ?? r.issues ?? ''
      }))
  }
}];

/**
 * MIRA — SCORE TEST CASE v4.1
 *
 * Node: Score Test Case
 * Mode: Run Once for All Items
 *
 * Deterministic evaluation for AI TPM workflows.
 *
 * Supports:
 * - Planner
 * - Risk Assessor
 * - Status Reporter
 * - Milestone Tracker
 * - Stakeholder Update
 *
 * Preserves existing downstream output contracts,
 * Google Sheets fields, and Langfuse scoring.
 *
 * Fixes:
 * - expectedSprint initialization error
 * - duplicate stakeholder scope validation
 * - stakeholder draft flag handling
 * - stakeholder citation extraction
 * - top-level TPM metric availability
 *
 * Does not independently verify factual grounding.
 */

// ==================================================
// 0. INPUT AND HELPERS
// ==================================================

const tc = $('Mark Test Start').first().json || {};
const res = $input.first()?.json || {};

const str = x => String(x ?? '').trim();
const arr = x => Array.isArray(x) ? x : [];

const obj = x =>
  x && typeof x === 'object' && !Array.isArray(x)
    ? x
    : {};

const num = x =>
  x !== null &&
  x !== undefined &&
  x !== '' &&
  Number.isFinite(Number(x))
    ? Number(x)
    : null;

const testId = str(tc.test_id);
const capability = str(tc.capability).toLowerCase();
const expected = str(tc.expected_behavior).toLowerCase();

const issues = [];
const warnings = [];
const checks = {};

function check(
  name,
  condition,
  failure,
  critical = true
) {
  const value =
    condition === null || condition === undefined
      ? null
      : Boolean(condition);

  checks[name] = {
    passed: value,
    critical
  };

  if (value === false) {
    (critical ? issues : warnings).push(failure);
  }

  return value;
}

// ==================================================
// 1. REPORT EXTRACTION
// ==================================================

const reports = obj(res.reports);

const aliases = {
  planner: 'plan',
  risk_assessor: 'risk',
  reporter: 'status',
  status_reporter: 'status',
  milestone_tracker: 'milestone',
  stakeholder: 'stakeholder_update'
};

const normalized = aliases[capability] || capability;

function unpack(x) {
  if (!x) return null;

  const y = obj(x);

  return Object.keys(obj(y.report)).length
    ? y.report
    : y;
}

const rawReport =
  reports[normalized] ||
  reports[capability] ||
  null;

const report = unpack(rawReport);

const noGeneratedReport =
  Object.keys(reports)
    .filter(k => reports[k] != null)
    .length === 0;

// ==================================================
// 2. EXECUTION AND LATENCY
// ==================================================

const latencyMs = Math.max(
  0,
  Date.now() - (num(tc.start_ms) ?? Date.now())
);

const validationPass =
  res.status === 'ok' &&
  res.overall_validation === 'passed';

const specialistStatus =
  str(report?.status).toLowerCase();

const specialistValidation =
  str(report?.validation_status).toLowerCase();

const specialistFailed =
  ['error', 'failed'].includes(specialistStatus) ||
  specialistValidation === 'failed';

const isGrounded = expected === 'grounded_output';
const isClarification = expected === 'needs_clarification';
const isNoData = expected === 'no_data';

const supportedExpected =
  isGrounded || isClarification || isNoData;

let passed = false;

// ==================================================
// 3. TEST ACCEPTANCE
// ==================================================

if (isGrounded) {

  check(
    'orchestrator_validation',
    validationPass,
    'Orchestrator validation did not pass'
  );

  check(
    'expected_report_present',
    Boolean(report),
    'Expected agent report is missing'
  );

  check(
    'specialist_not_failed',
    !specialistFailed,
    'Specialist report indicates failure'
  );

  if (report) {

    check(
      'report_snapshot_match',
      !str(tc.snapshot_id) ||
      !str(report.snapshot_id) ||
      str(report.snapshot_id) === str(tc.snapshot_id),
      'Specialist snapshot differs from expected snapshot'
    );

    check(
      'draft_only',
      report.is_draft !== false &&
      report.email_draft?.is_draft !== false &&
      report.update?.draft_only !== false,
      'Report or email is not marked draft'
    );
  }

} else if (isClarification) {

  const questions =
    arr(res.clarification_questions)
      .filter(x =>
        typeof x === 'string' && x.trim()
      );

  check(
    'clarification_status',
    res.status === 'needs_clarification',
    'Expected needs_clarification status'
  );

  check(
    'clarification_explanation',
    Boolean(str(res.message)),
    'Clarification explanation is missing'
  );

  check(
    'clarification_questions',
    questions.length > 0,
    'Expected at least one clarification question'
  );

  check(
    'no_generated_report',
    noGeneratedReport,
    'A report was generated despite missing details'
  );

} else if (isNoData) {

  const message = str(res.message);

  check(
    'insufficient_data_status',
    ['insufficient_data', 'needs_clarification']
      .includes(res.status),
    'Expected insufficient_data or needs_clarification'
  );

  const missingEvidenceExplained =
    /task|progress|status|sprint|completed|in.progress/i
      .test(message) &&
    /\b(cannot|unable|insufficient|unavailable|missing|lack|without)\b|not (provided|available)|\bno\b.{0,65}\b(snapshot|tasks?|data|evidence)\b|does not provide|doesn't provide/i
      .test(message);

  check(
    'missing_evidence_explained',
    missingEvidenceExplained,
    'Missing task/progress evidence was not explained'
  );

  check(
    'no_generated_report',
    noGeneratedReport,
    'Unexpected report generated without sufficient data'
  );

  check(
    'no_invented_percentage',
    !/\b\d+(?:\.\d+)?\s*%/.test(message),
    'Unexpected progress percentage in insufficient-data response'
  );

} else {

  issues.push(
    'Unknown expected_behavior: ' + expected
  );
}

// ==================================================
// 4. CITATION COVERAGE
// ==================================================

let claims = [];

if (normalized === 'plan') {

  claims = arr(report?.plan?.milestones).length
    ? arr(report.plan.milestones)
    : arr(report?.milestones);

} else if (normalized === 'risk') {

  claims = arr(report?.risks);

} else if (normalized === 'status') {

  claims = arr(report?.tasks);

} else if (normalized === 'milestone') {

  claims = [
    ...arr(report?.milestones),
    ...arr(report?.blocked_tasks)
  ];

} else if (normalized === 'stakeholder_update') {

  const update = obj(
    report?.update ??
    report?.stakeholder_update ??
    report
  );

  // Only structured, individually attributable claims
  // are counted here. The narrative email body is not
  // treated as a single cited claim.

  claims = [
    ...arr(update.accomplishments),
    ...arr(update.action_items),
    ...arr(update.risks_and_blockers)
  ].map(x => {

    if (typeof x === 'string') {
      return {
        text: x,
        source_reference: (
          x.match(/(?:source:\s*)([^),;\n]+)/i)?.[1] || ''
        ).trim()
      };
    }

    return x;
  });
}

const cited = claims.filter(x =>
  Boolean(
    str(x?.source_reference) ||
    str(x?.evidence) ||
    arr(x?.source_references).length
  )
).length;

const citationCoverage = claims.length
  ? Math.round(100 * cited / claims.length)
  : null;

if (isGrounded && claims.length) {

  check(
    'citation_presence',
    citationCoverage === 100,
    `Citation presence ${citationCoverage}% (target 100%)`,
    false
  );
}

if (
  isGrounded &&
  !claims.length &&
  [
    'plan',
    'risk',
    'status',
    'milestone',
    'stakeholder_update'
  ].includes(normalized)
) {

  warnings.push(
    'No itemized claims found for citation coverage'
  );
}

// ==================================================
// 5. TASK RECONCILIATION
// ==================================================

const tasks = arr(report?.tasks);

const normalizeStatus = x =>
  str(x).toLowerCase().replace(/[_-]/g, ' ');

const taskCounts = obj(report?.task_counts);

const counted = {
  total: tasks.length,

  completed: tasks.filter(
    t => normalizeStatus(t.status) === 'done'
  ).length,

  in_progress: tasks.filter(
    t => normalizeStatus(t.status) === 'in progress'
  ).length,

  not_started: tasks.filter(
    t => normalizeStatus(t.status) === 'to do'
  ).length,

  blocked: tasks.filter(
    t => normalizeStatus(t.status) === 'blocked'
  ).length
};

const uniqueIds = new Set(
  tasks.map(t => str(t.task_id)).filter(Boolean)
);

const taskReconciliation =
  normalized === 'status' &&
  isGrounded &&
  tasks.length
    ? (
        [
          'total',
          'completed',
          'in_progress',
          'not_started',
          'blocked'
        ].every(
          k => num(taskCounts[k]) === counted[k]
        ) &&
        uniqueIds.size === tasks.length &&
        counted.total ===
          counted.completed +
          counted.in_progress +
          counted.not_started +
          counted.blocked
      )
    : null;

if (normalized === 'status' && isGrounded) {

  check(
    'status_tasks_present',
    tasks.length > 0,
    'Status report has no task records'
  );

  if (tasks.length) {

    check(
      'task_reconciliation',
      taskReconciliation,
      'Task counts, statuses or task IDs do not reconcile'
    );

    check(
      'task_evidence_present',
      tasks.every(t =>
        str(t.task_id) &&
        str(t.status) &&
        str(t.evidence || t.source_reference)
      ),
      'Task ID/status/evidence missing'
    );
  }
}

// ==================================================
// 6. PROJECT AND SPRINT SCOPE
// ==================================================

// IMPORTANT:
// expectedSprint and scopeMatch are initialized here,
// before either status or stakeholder scope checks.

const requestText = str(
  tc.prompt ||
  tc.user_prompt ||
  tc.input ||
  tc.request_text ||
  ''
);

const requestedSprint =
  requestText.match(/\bSprint\s+(\d+)\b/i);

const expectedSprint = requestedSprint
  ? `Sprint ${requestedSprint[1]}`
  : null;

let scopeMatch = null;

// ---------- Status Reporter Scope ----------

if (
  normalized === 'status' &&
  isGrounded &&
  tasks.length &&
  requestText
) {

  scopeMatch = expectedSprint
    ? tasks.every(t =>
        str(t.sprint).toLowerCase() ===
        expectedSprint.toLowerCase()
      )
    : !/^Sprint\s+\d+$/i.test(
        str(report.report_period)
      );

  check(
    'sprint_scope',
    scopeMatch,
    'Task selection or reporting period conflicts with requested sprint'
  );
}

// ---------- Stakeholder Update Scope ----------

if (
  normalized === 'stakeholder_update' &&
  isGrounded &&
  report
) {

  const update = obj(
    report.update ??
    report.stakeholder_update ??
    report
  );

  const actualSprint =
    str(update.sprint).toLowerCase();

  const expectedSprintNormalized =
    str(expectedSprint).toLowerCase();

  scopeMatch = expectedSprint
    ? actualSprint === expectedSprintNormalized
    : null;

  if (scopeMatch !== null) {

    check(
      'stakeholder_sprint_scope',
      scopeMatch,
      'Stakeholder update sprint differs from requested sprint'
    );
  }
}

// ==================================================
// 7. SCHEDULE INTEGRITY
// ==================================================

const validDates = tasks
  .filter(t => str(t.due_date))
  .every(t =>
    /^\d{4}-\d{2}-\d{2}$/
      .test(str(t.due_date)) &&
    !Number.isNaN(
      Date.parse(str(t.due_date) + 'T00:00:00Z')
    )
  );

if (
  normalized === 'status' &&
  isGrounded &&
  tasks.length
) {

  check(
    'due_date_format',
    validDates,
    'Task due dates include invalid dates',
    false
  );
}

// Historical snapshots are not live task status.
// Do not infer overdue status using today's date.

// ==================================================
// 8. BLOCKER ACCOUNTABILITY
// ==================================================

const blockedTasks = tasks.filter(
  t => normalizeStatus(t.status) === 'blocked'
);

const blockerOwnerCoverage = blockedTasks.length
  ? Math.round(
      100 *
      blockedTasks.filter(t =>
        str(t.owner || t.assignee)
      ).length /
      blockedTasks.length
    )
  : null;

if (blockedTasks.length) {

  check(
    'blocker_owner_coverage',
    blockerOwnerCoverage === 100,
    'Blocked tasks lack assigned owners',
    false
  );
}

// ==================================================
// 9. RISK MANAGEMENT
// ==================================================

const risks = arr(report?.risks);

const riskCompleteness = risks.length
  ? Math.round(
      100 *
      risks.filter(r =>
        str(r.risk_id) &&
        str(r.impact) &&
        str(r.mitigation_strategy) &&
        str(r.source_reference || r.evidence)
      ).length /
      risks.length
    )
  : null;

if (normalized === 'risk' && isGrounded) {

  check(
    'risk_register_present',
    risks.length > 0,
    'Risk report has no risk register'
  );

  if (risks.length) {

    check(
      'risk_record_completeness',
      riskCompleteness === 100,
      'Risk entries missing ID, impact, mitigation or evidence',
      false
    );
  }
}


 // ==================================================
 // 10. MILESTONE MANAGEMENT
 // ==================================================

const milestones = arr(report?.milestones);

const hasMilestoneName = m =>
  Boolean(str(
    m.name ??
    m.milestone_name ??
    m.title
  ));

const hasMilestoneTimeReference = m => {
  const targetWeek = num(m.target_week);

  const hasWeek =
    targetWeek !== null &&
    Number.isInteger(targetWeek) &&
    targetWeek > 0;

  const hasDate = Boolean(str(
    m.due_date ??
    m.date ??
    m.target_date
  ));

  return hasWeek || hasDate;
};

const hasMilestoneEvidence = m =>
  Boolean(
    str(m.source_reference) ||
    str(m.evidence) ||
    arr(m.source_references).length > 0
  );

const validMilestone = m =>
  hasMilestoneName(m) &&
  hasMilestoneTimeReference(m) &&
  hasMilestoneEvidence(m);

const milestoneCompleteness = milestones.length
  ? Math.round(
      100 *
      milestones.filter(validMilestone).length /
      milestones.length
    )
  : null;

if (
  normalized === 'milestone' &&
  isGrounded &&
  milestones.length
) {
  check(
    'milestone_completeness',
    milestoneCompleteness === 100,
    'Milestone entries missing name, time reference or evidence',
    false
  );
}

// ==================================================
// 11. STAKEHOLDER COMMUNICATION SAFETY
// ==================================================

const email = obj(report?.email_draft);
const hasEmail = Object.keys(email).length > 0;

if (
  isGrounded &&
  (
    normalized === 'stakeholder_update' ||
    hasEmail
  )
) {

  const stakeholderUpdate = obj(
    report?.update ??
    report?.stakeholder_update
  );

  const stakeholderEmail = obj(
    stakeholderUpdate.email_draft ??
    report?.email_draft ??
    (hasEmail ? email : stakeholderUpdate)
  );

  const stakeholderDraftFlag =
    stakeholderUpdate.draft_only === true ||
    stakeholderUpdate.is_draft === true ||
    stakeholderEmail.draft_only === true ||
    stakeholderEmail.is_draft === true ||
    report?.draft_only === true ||
    report?.is_draft === true;

  check(
    'stakeholder_draft_flag',
    stakeholderDraftFlag,
    'Stakeholder email must be explicitly draft'
  );

  check(
    'stakeholder_email_content',
    Boolean(
      str(stakeholderEmail.subject) &&
      str(stakeholderEmail.body)
    ),
    'Stakeholder email subject or body is missing'
  );
}

// ==================================================
// 12. DATASET-DRIVEN ASSERTIONS
// ==================================================

const expectedAssertions = obj(
  tc.assertions || tc.expected_assertions
);

if (
  isGrounded &&
  tasks.length &&
  Object.keys(expectedAssertions).length
) {

  const expectedCounts = obj(
    expectedAssertions.task_counts
  );

  for (const [k, v] of Object.entries(expectedCounts)) {

    if (k in counted) {

      check(
        `expected_count_${k}`,
        num(v) === counted[k],
        `Expected ${k}=${v}, actual=${counted[k]}`
      );
    }
  }

  const requiredIds = arr(
    expectedAssertions.required_task_ids
  ).map(str);

  if (requiredIds.length) {

    check(
      'required_task_ids',
      requiredIds.every(id => uniqueIds.has(id)),
      'Required task IDs missing'
    );
  }

  const blockedIds = arr(
    expectedAssertions.blocked_task_ids
  ).map(str);

  if (blockedIds.length) {

    check(
      'required_blocked_task_ids',
      blockedIds.every(id =>
        blockedTasks.some(
          t => str(t.task_id) === id
        )
      ),
      'Expected blocked tasks not identified'
    );
  }
}

// ==================================================
// 13. FINAL ACCEPTANCE
// ==================================================

passed =
  supportedExpected &&
  Object.values(checks).every(
    c => !c.critical || c.passed === true
  ) &&
  issues.length === 0;

// ==================================================
// 14. TRACE ID AND LANGFUSE SCORES
// ==================================================

const now = new Date().toISOString();

const traceCandidates = [
  res.trace_id,
  res.root_trace_id,
  report?.trace_id,
  report?.root_trace_id
];

const traceId = traceCandidates.find(
  x => /^[0-9a-f]{32}$/i.test(str(x))
) || null;

const uuid = () =>
  'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'
    .replace(/[xy]/g, c => {

      const r = Math.floor(Math.random() * 16);

      return (
        c === 'x'
          ? r
          : (r & 3 | 8)
      ).toString(16);
    });

const score = (name, value) => {

  const id = uuid();

  return {
    id,
    timestamp: now,
    type: 'score-create',

    body: {
      id,
      traceId,
      name,
      value
    }
  };
};

const langfuseBatch = traceId
  ? [
      score(
        'smoke_pass',
        passed ? 1 : 0
      ),

      ...(
        isGrounded
          ? [
              score(
                'validation_pass',
                validationPass ? 1 : 0
              )
            ]
          : []
      ),

      ...(
        taskReconciliation !== null
          ? [
              score(
                'task_reconciliation',
                taskReconciliation ? 1 : 0
              )
            ]
          : []
      ),

      ...(
        citationCoverage !== null
          ? [
              score(
                'citation_presence_pct',
                citationCoverage
              )
            ]
          : []
      )
    ]
  : [];

if (!traceId) {

  warnings.push(
    'Langfuse scoring skipped: no valid trace ID'
  );
}

// ==================================================
// 15. GROUNDING STATUS
// ==================================================

if (isGrounded) {

  warnings.push(
    'Factual grounding against original source documents not independently verified'
  );

} else {

  warnings.push(
    'Specialist validation not applicable: no report expected'
  );
}

if (
  isGrounded &&
  !Object.keys(expectedAssertions).length
) {

  warnings.push(
    'No dataset-specific assertions supplied; TPM content acceptance is limited'
  );
}

// ==================================================
// 16. RETURN RESULT
// ==================================================

return [{
  json: {

    // Execution metadata
    run_at: now,
    test_id: testId,
    capability,
    expected_behavior: expected,

    // Functional evaluation
    passed,
    smoke_pass: passed,
    validation_pass: validationPass,

    // Citation metrics
    citation_coverage_pct: citationCoverage,
    source_claim_count: claims.length,
    cited_claim_count: cited,

    // TPM metrics exposed for Evaluation History
    task_reconciliation_pass: taskReconciliation,
    scope_match: scopeMatch,

    // Independent grounding is evaluated downstream
    grounding_coverage: null,
    grounding_verified: false,

    // Performance
    latency_ms: latencyMs,

    // Evaluation findings
    issues: issues.join(' | '),
    warnings,

    // Trace
    trace_id: traceId,

    // Agent output
    actual_output: JSON.stringify(report || res),
    agent_output: report,

    // Langfuse
    langfuse_batch: langfuseBatch,

    // Existing nested TPM contract
    tpm_metrics: {
      checks,

      task_reconciliation: taskReconciliation,
      scope_match: scopeMatch,

      blocked_task_count: blockedTasks.length,
      blocker_owner_coverage_pct:
        blockerOwnerCoverage,

      risk_record_completeness_pct:
        riskCompleteness,

      milestone_completeness_pct:
        milestoneCompleteness,

      task_counts: counted,

      source_claim_count: claims.length,
      cited_claim_count: cited,

      latency_ms: latencyMs
    },

    // Version
    evaluation_version: '4.1'
  }
}];

