/**
 * MIRA — RESOLVE EXISTING SNAPSHOT v2.0
 *
 * Selects a complete, validated project snapshot.
 * Prevents accidental cross-project selection.
 * Preserves downstream output fields.
 */

const rows = $input.all().map(item => item.json || {});
const pinnedSnapshotId =
  'ABCDE-LTD-AI-ADOPTION-20261102021744-021e119b';

const requiredKinds = [
  'project_description',
  'risks',
  'timeline',
  'task_board'
];

// Set the project being evaluated.
// For baseline evaluation, use the approved project.
const targetProject = 'ABCDE Ltd AI Adoption';

// Optional: pin a specific snapshot for reproducibility.
// Leave blank to select the latest validated snapshot.
//const pinnedSnapshotId = '';

const normalize = value =>
  String(value ?? '').trim().toLowerCase();

const parseReport = value => {
  if (!value) return null;

  if (
    typeof value === 'object' &&
    !Array.isArray(value)
  ) {
    return value;
  }

  try {
    const parsed = JSON.parse(value);

    return parsed &&
      typeof parsed === 'object' &&
      !Array.isArray(parsed)
        ? parsed
        : null;

  } catch {
    return null;
  }
};

// --------------------------------------------------
// 1. GROUP FILES BY SNAPSHOT
// --------------------------------------------------

const groups = new Map();

for (const row of rows) {

  const id = String(row.snapshot_id || '').trim();

  if (!id) continue;

  if (!groups.has(id)) {
    groups.set(id, []);
  }

  groups.get(id).push(row);
}

// --------------------------------------------------
// 2. VALIDATE SNAPSHOT CANDIDATES
// --------------------------------------------------

const candidates = [];

for (const [snapshotId, files] of groups) {

  if (
    pinnedSnapshotId &&
    snapshotId !== pinnedSnapshotId
  ) {
    continue;
  }

  // Project isolation:
  // Prefer explicit project fields when available.
  const projectNames = files
    .map(file =>
      file.project_name ||
      file.project ||
      ''
    )
    .filter(Boolean);

  const projectMatches = projectNames.length
    ? projectNames.every(
        name => normalize(name) ===
          normalize(targetProject)
      )
    : snapshotId.toLowerCase()
        .startsWith('abcde-ltd-ai-adoption-');

  if (!projectMatches) continue;

  const kinds = new Set(
    files.map(file =>
      String(file.doc_kind || '').trim()
    )
  );

  const complete = requiredKinds.every(
    kind => kinds.has(kind)
  );

  if (!complete) continue;

  // Require a validated task board.
  const taskBoards = files.filter(
    file => file.doc_kind === 'task_board'
  );

  if (taskBoards.length !== 1) continue;

  const taskBoard = taskBoards[0];

  const taskReport = parseReport(
    taskBoard.validation_report
  );

  const validated =
    taskReport?.validation_passed === true &&
    taskReport?.ready_for_mira === true;

  if (!validated) continue;

  // Reject explicit validation failures
  // on any required source document.
  const requiredFiles = files.filter(
    file => requiredKinds.includes(
      String(file.doc_kind || '').trim()
    )
  );

  const explicitFailure = requiredFiles.some(
    file => {
      const report = parseReport(
        file.validation_report
      );

      return (
        report?.validation_passed === false ||
        report?.ready_for_mira === false
      );
    }
  );

  if (explicitFailure) continue;

  const timestamps = files
    .map(file =>
      Date.parse(file.uploaded_at || '')
    )
    .filter(Number.isFinite);

  const latestTime = timestamps.length
    ? Math.max(...timestamps)
    : 0;

  candidates.push({
    snapshot_id: snapshotId,
    uploaded_at_ms: latestTime,
    file_count: files.length,
    validated: true,
    project_name: targetProject,
    required_kinds: requiredKinds
  });
}

// --------------------------------------------------
// 3. DETERMINISTIC SELECTION
// --------------------------------------------------

candidates.sort((a, b) => {

  const dateDifference =
    b.uploaded_at_ms - a.uploaded_at_ms;

  if (dateDifference !== 0) {
    return dateDifference;
  }

  return a.snapshot_id.localeCompare(
    b.snapshot_id
  );
});

if (candidates.length === 0) {

  throw new Error(
    `No complete, validated snapshot found for ${targetProject}`
  );
}

const selected = candidates[0];

// --------------------------------------------------
