/**
 * MIRA — Discover Child Execution v2.1
 *
 * Supports:
 * 1. n8n execution API responses
 * 2. Direct Orchestrator clarification/no-data responses
 *
 * Mode: Run Once for All Items
 */

const execution = $input.first()?.json ?? {};

const runData =
  execution.data?.resultData?.runData ?? {};

let testCaseId = null;
let capability = null;

try {
  const testCase = $('Mark Test Start').first().json;

  testCaseId = testCase.test_id ?? null;
  capability = testCase.capability ?? null;
} catch {}

// -----------------------------------------
// 1. Capability mapping
// -----------------------------------------

const capabilityConfig = {
  plan: {
    agent: 'plan',
    nodeNames: ['Planner Agent', 'Planning Agent']
  },
  risk: {
    agent: 'risk',
    nodeNames: ['Risk Assessor Agent', 'Risk Assessment Agent']
  },
  status: {
    agent: 'status',
    nodeNames: ['Status Reporter Agent', 'Status Report Agent']
  },
  milestone: {
    agent: 'milestone',
    nodeNames: ['Milestone Tracker Agent']
  },
  stakeholder_update: {
    agent: 'stakeholder_update',
    nodeNames: ['Stakeholder Update Agent']
  }
};

const config = capabilityConfig[capability] ?? null;

const directResult =
  execution.orchestrator_result &&
  typeof execution.orchestrator_result === 'object'
    ? execution.orchestrator_result
    : execution;

const directStatus =
  String(directResult.status ?? '').toLowerCase();

const isDirectNegative =
  ['needs_clarification', 'insufficient_data', 'no_data']
    .includes(directStatus);

const orchestratorExecutionId =
  execution.id != null
    ? String(execution.id)
    : execution.orchestrator_execution_id != null
      ? String(execution.orchestrator_execution_id)
      : null;

const traceId =
  directResult.trace_id ??
  execution.trace_id ??
  execution.data?.trace_id ??
  null;

function result(status, reason, child = null, agent = capability) {
  return [{
    json: {
      orchestrator_execution_id: orchestratorExecutionId,

      execution_id:
        child?.executionId != null
          ? String(child.executionId)
          : null,

      workflow_id:
        child?.workflowId != null
          ? String(child.workflowId)
          : null,

      trace_id: traceId,
      test_case_id: testCaseId,
      agent_name: agent ?? null,
      discovery_status: status,
      discovery_reason: reason,

      orchestrator_status:
        directResult.status ?? null,

      direct_result:
        isDirectNegative ? directResult : null,

      execution_fetch_skipped:
        execution.execution_fetch_skipped === true
    }
  }];
}

// -----------------------------------------
// 2. Direct clarification/no-data response
// -----------------------------------------

if (isDirectNegative) {
  return result(
    'not_required',
    'Orchestrator returned a clarification/no-data response; no specialist child execution expected',
    null,
    directResult.agent ?? 'orchestrator'
  );
}

// -----------------------------------------
// 3. Validate capability
// -----------------------------------------

if (!config) {
  return result(
    'not_found',
    capability
      ? `Unsupported capability: ${capability}`
      : 'Evaluation capability is missing'
  );
}

// -----------------------------------------
// 4. Locate specialist agent
// -----------------------------------------

const matchingNodes =
  Object.entries(runData).filter(
    ([nodeName]) => config.nodeNames.includes(nodeName)
  );

if (matchingNodes.length === 0) {
  return result(
    'not_found',
    `No matching orchestrator node found. Available nodes: ${Object.keys(runData).join(', ')}`,
    null,
    config.agent
  );
}

// -----------------------------------------
// 5. Discover child execution metadata
// -----------------------------------------

const children = [];

for (const [nodeName, runs] of matchingNodes) {
  for (const run of runs ?? []) {
    const metadata = run.metadata ?? {};

    for (const candidate of [
      metadata.subExecution,
      metadata.subExecutionData
    ]) {
      if (!candidate) continue;

      const executionId =
        candidate.executionId ??
        candidate.execution_id ??
        null;

      const workflowId =
        candidate.workflowId ??
        candidate.workflow_id ??
        null;

      if (executionId == null || workflowId == null) {
        continue;
      }

      children.push({
        executionId,
        workflowId,
        nodeName,
        startTime: run.startTime ?? 0
      });
    }
  }
}

// -----------------------------------------
// 6. Final result
// -----------------------------------------

if (children.length === 0) {
  return result(
    'not_found',
    'Matching agent node found, but no valid child execution metadata was available',
    null,
    config.agent
  );
}

children.sort((a, b) => a.startTime - b.startTime);

const child = children[children.length - 1];

return result(
  'success',
  `Child execution discovered from ${child.nodeName}`,
  child,
  config.agent
);

/**
 * MIRA — Restore Agent Result + Token Metrics v1.1
 *
 * Works with:
 * - Positive tests with specialist token metrics
 * - Negative tests returning clarification
 * - Missing or unavailable token telemetry
 *
 * Token usage is observability metadata,
 * never project evidence.
 */

const orchestrator =
  $('Run Mira Orchestrator').first().json;

const input = $input.first()?.json ?? {};

const hasSpecialistExecution =
  Number.isInteger(Number(input.execution_id)) &&
  Number(input.execution_id) > 0;

const isClarification =
  orchestrator.status === 'needs_clarification' ||
  orchestrator.report === null;

const pickNumber = (...values) => {
  for (const value of values) {
    if (
      value === null ||
      value === undefined ||
      value === ''
    ) {
      continue;
    }

    const number = Number(value);

    if (Number.isFinite(number) && number >= 0) {
      return number;
    }
  }

  return null;
};

const hasUsage =
  input.generation_input_tokens != null ||
  input.generation_output_tokens != null ||
  input.generation_total_tokens != null;

const result = {
  ...orchestrator,

  generation_input_tokens: hasUsage
    ? pickNumber(input.generation_input_tokens)
    : null,

  generation_output_tokens: hasUsage
    ? pickNumber(input.generation_output_tokens)
    : null,

  generation_total_tokens: hasUsage
    ? pickNumber(input.generation_total_tokens)
    : null,

  generation_model:
    input.generation_model ??
    input.model ??
    null,

  model_call_count:
    pickNumber(input.model_call_count),

  generation_observation_count:
    pickNumber(input.generation_observation_count),

  langfuse_export_submitted:
    input.langfuse_export_submitted === true,

  langfuse_ingestion_confirmed:
    input.langfuse_ingestion_confirmed === true,

  token_usage_available: hasUsage,

  token_collection_status: hasUsage
    ? 'collected'
    : isClarification
      ? 'not_collected_clarification'
      : 'not_available',

  specialist_execution_available:
    hasSpecialistExecution,

  trace_id:
    orchestrator.trace_id ??
    input.trace_id ??
    null
};

return [{ json: result }];

